WITH desired AS (SELECT pb.id_user,pb.id_record,points.points AS level_points,RANK() OVER(ORDER BY record.time)::integer AS level_position FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public.level_points points ON points.id_level=pb.id_level WHERE pb.id_level=$1 AND points.points>0), calculated AS (SELECT *,(CASE WHEN ln(level_points::double precision)+(level_position-1)*ln(0.985)<ln(1.401298464324817e-45) THEN 0 ELSE level_points::double precision*power(0.985,level_position-1) END)::real AS decayed FROM desired), current AS (SELECT * FROM public.user_point_contribution WHERE id_level=$1) SELECT EXISTS(SELECT 1 FROM calculated target FULL JOIN current ON current.id_user=target.id_user WHERE target.id_user IS NULL OR current.id_user IS NULL OR ROW(current.id_record,current.level_position,current.level_points,current.level_decayed_points) IS DISTINCT FROM ROW(target.id_record,target.level_position,target.level_points,target.decayed) LIMIT 1) AS value
